-- GENERATED by scripts/build-seed.mjs from src/data/mock/seed/*.json. Do not edit by hand.
-- Demo data only (is_demo = true, fictional names). Run once on a demo project after the migrations:
-- it creates the demo accounts (password: madad-demo-2026), turns on demo_mode, and loads the data.
-- demo_reset() (the role switcher's «إعادة ضبط بيانات العرض») runs demo_seed() again.

create or replace function public.demo_seed() returns void
language plpgsql security definer set search_path = ''
as $seed$
begin
  perform set_config('madad.audit', 'off', true);
  truncate public.organizations, public.medicines, public.categories, public.search_logs, public.page_views,
    public.reports, public.audit_log, public.notifications, public.favorites, public.availability_alerts,
    public.inquiries, public.announcements cascade;
  update public.settings set value = case key
    when 'fresh_hours' then '24'::jsonb
    when 'expire_hours' then '72'::jsonb
    when 'price_max_days' then '14'::jsonb
    when 'program_confirm_days' then '7'::jsonb
    when 'disclaimer_ar' then 'null'::jsonb
    when 'disclaimer_en' then 'null'::jsonb
    when 'required_docs' then '{"pharmacy":["practice_license","pharmacy_license","contact_id"],"hospital":["facility_license","contact_id"],"medical_point":["authorization_letter","contact_id"],"humanitarian":["registration_certificate","contact_id"]}'::jsonb
    when 'rejection_reasons' then '["وثائق غير واضحة أو ناقصة","الرخصة غير سارية","البيانات لا تطابق الوثائق","مؤسسة مكررة"]'::jsonb
    else value end
  where key <> 'demo_mode';

  update public.profiles set full_name = 'مريض تجريبي', phone = null, platform_role = null, is_demo = true where id = 'dd4ed580-9bd4-37bb-edb0-475baf3f6f9e'::uuid;
  update public.profiles set full_name = 'مالك صيدلية تجريبي', phone = null, platform_role = null, is_demo = true where id = '44744379-1792-1678-8d4f-7d7f3ee28093'::uuid;
  update public.profiles set full_name = 'موظف صيدلية تجريبي', phone = null, platform_role = null, is_demo = true where id = 'be97c99d-48cb-5a85-fbdc-9d038b8a4851'::uuid;
  update public.profiles set full_name = 'مالك مؤسسة تجريبي', phone = null, platform_role = null, is_demo = true where id = '9e9be1e8-7588-51cb-6719-0b6426c97166'::uuid;
  update public.profiles set full_name = 'مراجِع تجريبي', phone = null, platform_role = 'reviewer', is_demo = true where id = '4b6a0cf3-57b2-b00e-cafb-2ff25d4e7e6f'::uuid;
  update public.profiles set full_name = 'مدير نظام تجريبي', phone = null, platform_role = 'super_admin', is_demo = true where id = 'd0b7ce98-4dad-b70b-5f93-286c115ea944'::uuid;
  update public.profiles set full_name = 'سارة م.', phone = null, platform_role = null, is_demo = true where id = 'e58304b9-dccb-1356-e052-20ffc7626584'::uuid;
  update public.profiles set full_name = 'أبو خالد', phone = null, platform_role = null, is_demo = true where id = '6f89da1b-c5f6-0ffa-0b7d-4d46d4cce0b9'::uuid;

















  perform set_config('madad.audit', '', true);
end;
$seed$;
revoke execute on function public.demo_seed() from public, anon, authenticated;

